<?php
declare(strict_types=1);
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();header('Cache-Control: no-store, private');
require_once dirname(__DIR__).'/app/bootstrap.php';
function invoiceSummaryH(string|int|float|null $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$user=$_SESSION['user']??null;if(!is_array($user)||($user['role']??'')!=='coach'){http_response_code(403);exit('Auftragsabrechnungen sind Coaches vorbehalten.');}
$db=coachingDatabase();$coach=(int)$user['id'];$orderId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;
$q=$db->prepare("SELECT a.id,a.titel,a.erstellt_am,a.abgeschlossen_am,k.id AS klient_id,k.vorname,k.nachname,k.kundennummer FROM coaching_auftraege a INNER JOIN klienten k ON k.id=a.klient_id WHERE a.id=:id AND a.coach_benutzer_id=:coach AND k.benutzer_id=:owner");$q->execute(['id'=>$orderId,'coach'=>$coach,'owner'=>$coach]);$order=$q->fetch(PDO::FETCH_ASSOC);if(!$order){http_response_code(404);exit('Coaching-Auftrag nicht gefunden.');}
$q=$db->prepare('SELECT id,rechnungsnummer,status,rechnungsdatum,faellig_am,bezahlt_am,sitzung_beginn,dauer_minuten,leistungsbeschreibung,steuersatz_bezeichnung,steuersatz,netto,steuerbetrag,brutto FROM coaching_rechnungen WHERE coach_benutzer_id=:coach AND klient_id=:client AND auftrag_id=:order ORDER BY sitzung_beginn,id');$q->execute(['coach'=>$coach,'client'=>(int)$order['klient_id'],'order'=>$orderId]);$invoices=$q->fetchAll(PDO::FETCH_ASSOC);
$totals=['net'=>0.0,'tax'=>0.0,'gross'=>0.0,'paid'=>0.0,'due'=>0.0];$taxGroups=[];
foreach($invoices as $invoice){if(!in_array($invoice['status'],['gestellt','bezahlt'],true))continue;$net=(float)$invoice['netto'];$tax=(float)$invoice['steuerbetrag'];$gross=(float)$invoice['brutto'];$totals['net']+=$net;$totals['tax']+=$tax;$totals['gross']+=$gross;if($invoice['status']==='bezahlt')$totals['paid']+=$gross;else$totals['due']+=$gross;$key=(string)$invoice['steuersatz_bezeichnung'].'|'.(string)$invoice['steuersatz'];if(!isset($taxGroups[$key]))$taxGroups[$key]=['label'=>$invoice['steuersatz_bezeichnung'],'rate'=>(float)$invoice['steuersatz'],'net'=>0.0,'tax'=>0.0];$taxGroups[$key]['net']+=$net;$taxGroups[$key]['tax']+=$tax;}
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Auftragsabrechnung</title><link rel="stylesheet" href="assets/layout.css"><style>
body{background:#f3f5f3;color:#24332d}.page{max-width:1050px;margin:24px auto 60px;padding:0 24px}.sheet{background:white;border:1px solid #e4ebe6;border-radius:14px;padding:30px;margin-top:16px}.actions{display:flex;gap:10px;flex-wrap:wrap}.button{background:#245c50;color:white;border:0;border-radius:8px;padding:10px 14px;text-decoration:none;font:inherit;cursor:pointer}.button.light{background:#edf5ef;color:#245c50}.notice{background:#edf5ef;padding:13px;border-radius:9px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.stat{padding:14px;background:#f5f7f5;border-radius:10px}.stat small{display:block;color:#718078}.table{width:100%;border-collapse:collapse;margin-top:20px}.table th,.table td{text-align:left;padding:10px 8px;border-bottom:1px solid #e8eeea}.num{text-align:right!important;white-space:nowrap}.muted{font-size:12px;color:#718078}@media(max-width:750px){.grid{grid-template-columns:1fr 1fr}.table-wrap{overflow:auto}}@media print{body{background:white}.page{margin:0;max-width:none;padding:0}.actions{display:none}.sheet{border:0;box-shadow:none;margin:0;padding:14mm}.notice{background:white;border:1px solid #aaa}@page{size:A4;margin:0}}
</style></head><body><main class="page"><div class="actions"><a class="button light" href="invoices.php">← Rechnungen</a><button class="button" onclick="window.print()">Übersicht drucken / PDF</button></div>
<section class="sheet"><h1>Auftragsabrechnung</h1><p><strong><?=invoiceSummaryH($order['vorname'].' '.$order['nachname'])?></strong> · <?=invoiceSummaryH($order['titel'])?><br>Kundennummer: <?=invoiceSummaryH($order['kundennummer']??'—')?> · Auftrag seit <?=invoiceSummaryH(date('d.m.Y',strtotime($order['erstellt_am'])))?></p><p class="notice">Diese Übersicht fasst bereits erstellte Einzelrechnungen zusammen. Sie ist keine zusätzliche Rechnung und erzeugt keine neue Forderung.</p>
<div class="grid"><div class="stat"><small>Ausgestellte Rechnungen, netto</small><strong><?=number_format($totals['net'],2,',','.')?> EUR</strong></div><div class="stat"><small>Steuer gesamt</small><strong><?=number_format($totals['tax'],2,',','.')?> EUR</strong></div><div class="stat"><small>Brutto ausgestellt</small><strong><?=number_format($totals['gross'],2,',','.')?> EUR</strong></div><div class="stat"><small>Noch offen</small><strong><?=number_format($totals['due'],2,',','.')?> EUR</strong></div></div>
<h2>Rechnungen</h2><?php if(!$invoices):?><p class="muted">Für diesen Auftrag wurden noch keine Rechnungen erstellt.</p><?php else:?><div class="table-wrap"><table class="table"><thead><tr><th>Nummer / Status</th><th>Sitzung</th><th>Leistung</th><th>Netto</th><th>Steuersatz</th><th>Brutto</th></tr></thead><tbody><?php foreach($invoices as $invoice):?><tr><td><?php if($invoice['rechnungsnummer']):?><a href="invoice-view.php?id=<?=(int)$invoice['id']?>"><?=invoiceSummaryH($invoice['rechnungsnummer'])?></a><?php else:?>Entwurf #<?=(int)$invoice['id']?><?php endif;?><br><span class="muted"><?=invoiceSummaryH($invoice['status'])?><?= $invoice['rechnungsdatum']?' · '.invoiceSummaryH(date('d.m.Y',strtotime($invoice['rechnungsdatum']))):''?></span></td><td><?=invoiceSummaryH(date('d.m.Y',strtotime($invoice['sitzung_beginn'])))?></td><td><?=invoiceSummaryH($invoice['leistungsbeschreibung'])?></td><td><?=number_format((float)$invoice['netto'],2,',','.')?> EUR</td><td><?=invoiceSummaryH($invoice['steuersatz_bezeichnung'])?> (<?=number_format((float)$invoice['steuersatz'],2,',','.')?> %)<br><span class="muted"><?=number_format((float)$invoice['steuerbetrag'],2,',','.')?> EUR Steuer</span></td><td><?=number_format((float)$invoice['brutto'],2,',','.')?> EUR</td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<h2>Steueraufteilung der ausgestellten Rechnungen</h2><?php if(!$taxGroups):?><p class="muted">Noch keine ausgestellten Rechnungen.</p><?php else:foreach($taxGroups as $group):?><p><?=invoiceSummaryH($group['label'])?> (<?=number_format($group['rate'],2,',','.')?> %): Netto <?=number_format($group['net'],2,',','.')?> EUR · Steuer <?=number_format($group['tax'],2,',','.')?> EUR</p><?php endforeach;endif;?>
<p class="muted">Bezahlt: <?=number_format($totals['paid'],2,',','.')?> EUR · Ausgestellt und offen: <?=number_format($totals['due'],2,',','.')?> EUR</p></section></main></body></html>